<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { directions, type Screen, type Variant } from '../../data/prototype'
const current = ref<Screen>('home')
const reduced = ref(Boolean(uni.getStorageSync('qingjian-prototype:reduced-motion')))
const screens: { id: Screen; name: string }[] = [{ id: 'home', name: '首页' }, { id: 'templates', name: '模板列表' }, { id: 'editor', name: '简历编辑' }, { id: 'preview', name: '生成预览' }]
const origin = ref('')
const refresh = ref(0)
const href = computed(() => Object.fromEntries(directions.map(d => [d.id, `${origin.value}#/pages/${d.id}/index?view=${current.value}&r=${refresh.value}`])))
function open(variant: Variant) { uni.navigateTo({ url: `/pages/${variant}/index?view=${current.value}` }) }
function motion() { reduced.value = !reduced.value; uni.setStorageSync('qingjian-prototype:reduced-motion', reduced.value); refresh.value++ }
onMounted(() => {
  // #ifdef H5
  origin.value = window.location.href.split('#')[0]
  // #endif
})
</script>
<template>
  <view class="review-page">
    <view class="review-header"><view class="review-brand"><view class="review-brand-symbol">履</view><text>轻简履 <text class="review-brand-en">DESIGN EXPLORATION</text></text></view><view class="review-phase"><view />第一阶段 · 代表页面审阅</view></view>
    <view class="review-intro"><view><text class="review-eyebrow">THREE WAYS TO YOUR NEXT CHAPTER.</text><text class="review-title">一份简历，三种新的开始。</text><text class="review-subtitle">清新淡雅的三种表达。相同业务内容，不同的布局、字体与编辑方式。</text></view><view class="review-scope"><text>首页 / 模板 / 编辑</text><text>可操作原型 · 虚构示例数据</text><text>草稿仅保存在当前设备</text></view></view>
    <view class="review-controls"><view class="review-tabs"><button role="button" v-for="item in screens" :key="item.id" :class="{ active: current === item.id }" @click="current = item.id">{{ item.name }}</button></view><button role="button" class="motion-switch" :class="{ enabled: reduced }" @click="motion"><view><view /></view>{{ reduced ? '已减少动态' : '减少动态' }}</button></view>
    <view class="directions-grid">
      <view v-for="item in directions" :key="item.id" class="direction-card" :style="{ '--direction-color': item.color }"><view class="direction-heading"><view class="direction-letter">{{ item.letter }}</view><view><view class="direction-title-row"><text class="direction-name">{{ item.name }}</text><text class="direction-tag">{{ item.tag }}</text></view><text class="direction-subtitle">{{ item.subtitle }}</text></view><button role="button" class="direction-open" @click="open(item.id)">独立体验 ↗</button></view>
        <!-- #ifdef H5 -->
        <view class="phone-shell"><iframe v-if="origin" :key="item.id + current + refresh" :src="href[item.id]" :title="item.name + '方案可操作预览'" class="prototype-frame" /></view>
        <!-- #endif -->
        <!-- #ifndef H5 -->
        <button role="button" class="native-direction-entry" @click="open(item.id)"><text>{{ item.layout }}</text><text>点击打开可操作方案 →</text></button>
        <!-- #endif -->
        <view class="direction-caption"><text class="direction-layout">{{ item.layout }}</text><text>{{ item.description }}</text><text class="direction-tradeoff">{{ item.tradeoff }}</text></view>
      </view>
    </view>
    <view class="review-footnote"><view><text>建议先体验：选择模板 → 用这个样式 → 编辑信息 → 保存或生成预览。</text><text>青屿适合低门槛快速制作；素笺强调个人表达；晴空适合需要步骤引导的用户。</text></view><text class="review-limit">此入口为同源 H5 体验，顶部微信胶囊为模拟占位。微信小程序编译与真实设备验收单独记录；支付、AI、证件照和真实导出尚未接入。</text></view>
  </view>
</template>
